pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance = (cpu_norm - ram_norm).abs();

    // Non-linear penalty for imbalance
    let mut score = imbalance * imbalance;

    // Penalize if the residual capacity is too low
    if node_residual_cpu < job_cpu || node_residual_ram < job_ram {
        score += 10.0;
    }

    // Lookahead awareness: Prefer nodes that can fit the next job perfectly or complement it well
    let next_job_norm_cpu = (node_capacity_cpu - next_job_cpu) as f64 / node_capacity_cpu as f64;
    let next_job_norm_ram = (node_capacity_ram - next_job_ram) as f64 / node_capacity_ram as f64;
    let next_imbalance = (next_job_norm_cpu - next_job_norm_ram).abs();

    if next_job_norm_cpu >= 0.5 && next_job_norm_ram >= 0.5 {
        score -= 2.0; // Prefer nodes that can fit the next job well
    } else if next_imbalance < imbalance {
        score += 1.0; // Prefer nodes with a better balance for future jobs
    }

    // Time horizon awareness: Penalize nodes that will quickly become overloaded
    let time_horizon = step_index as f64 / total_jobs as f64;
    if time_horizon < 0.5 {
        score += (1.0 - time_horizon) * 5.0; // Prefer nodes with more remaining time
    } else {
        score -= (time_horizon - 0.5) * 5.0; // Penalize nodes with less remaining time
    }

    // Lookahead packing bonuses: Reward nodes that can pack the next job well
    if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        score -= 1.5; // Prefer nodes that can pack the next job well
    }

    // Combine fine-grained residual fitting with lookahead anticipation
    let residual_fit_score = (node_residual_cpu as f64 / mean_cpu_residual).powi(2) + (node_residual_ram as f64 / mean_ram_residual).powi(2);
    if residual_fit_score < 1.0 {
        score -= residual_fit_score * 5.0; // Penalize nodes with poor fine-grained residual fitting
    } else {
        score += residual_fit_score * 2.0; // Reward nodes with good fine-grained residual fitting
    }

    // Additional refinement: Penalize nodes with high dead space ratio
    let cpu_dead_space = (node_capacity_cpu - node_residual_cpu) as f64 / node_capacity_cpu as f64;
    let ram_dead_space = (node_capacity_ram - node_residual_ram) as f64 / node_capacity_ram as f64;
    score += (cpu_dead_space + ram_dead_space) * 2.0; // Penalize nodes with high dead space ratio

    score
}

